+import { db } from "../lib/db";
+import { currentPeriod } from "../billing/period";
+import { planFor } from "../billing/plans";
+
+export interface UsageSummary {
+  periodStart: string;
+  periodEnd: string;
+  apiCalls: number;
+  apiCallLimit: number;
+  overageRateCents: number;
+  seatsUsed: number;
+  seatsIncluded: number;
+  projectedInvoiceCents: number;
+}
+
+export async function getUsageSummary(accountId: string): Promise<UsageSummary> {
+  const period = await currentPeriod(accountId);
+  const plan = await planFor(accountId);
+  const apiCalls = await db.usageEvents.count({ accountId, since: period.start });
+  const seatsUsed = await db.members.count({ accountId, active: true });
+  const overage = Math.max(0, apiCalls - plan.apiCallLimit);
+  return {
+    periodStart: period.start,
+    periodEnd: period.end,
+    apiCalls,
+    apiCallLimit: plan.apiCallLimit,
+    overageRateCents: plan.overageRateCents,
+    seatsUsed,
+    seatsIncluded: plan.seats,
+    projectedInvoiceCents: plan.priceCents + overage * plan.overageRateCents,
+  };
+}
